// Your handler joins the SAME dispatcher, above the NavHost's while it is on screen
@Composable
fun EditorScreen(dirty: Boolean, onDiscard: () -> Unit) {
  var confirming by remember { mutableStateOf(false) }
  BackHandler(enabled = dirty) { confirming = true }   // toggle enabled, never decide inside
  if (confirming) DiscardDialog(onConfirm = onDiscard, onDismiss = { confirming = false })
}

// popBackStack() reports whether it did anything; at the root it returns false
fun leaveScreen(navController: NavController, activity: Activity) {
  if (!navController.popBackStack()) activity.finish()   // nothing left to pop: leave the task
}

