// ✅ One call: land on Home and take the entire auth graph off the stack with it
fun NavController.onSignedIn() = navigate(Home) {
  popUpTo<AuthGraph> { inclusive = true }   // without inclusive, Back returns to Login
  launchSingleTop = true                    // a double tap must not stack a second Home
}

// Sign-out is the mirror image: erase everything, start destination included
fun NavController.onSignedOut() = navigate(AuthGraph) {
  popUpTo(graph.findStartDestination().id) { inclusive = true }
  launchSingleTop = true
}

