private data class Tab(val route: Any, val icon: ImageVector, val label: String)

@Composable
fun RootScaffold(tabs: List<Tab>) {
  val navController = rememberNavController()
  val entry by navController.currentBackStackEntryAsState()

  Scaffold(bottomBar = {
    NavigationBar {
      tabs.forEach { tab ->
        NavigationBarItem(
          // hierarchy, so a tab stays selected while the user is deep inside it
          selected = entry?.destination?.hierarchy?.any { it.hasRoute(tab.route::class) } == true,
          onClick = {
            navController.navigate(tab.route) {
              // stash the tab we are leaving, under the start destination we pop to
              popUpTo(navController.graph.findStartDestination().id) { saveState = true }
              launchSingleTop = true   // repeated taps must not stack tab roots
              restoreState = true      // bring this tab's own stack back if we saved one
            }
          },
          icon = { Icon(tab.icon, null) },
          label = { Text(tab.label) }
        )
      }
    }
  }) { padding ->
    NavHost(navController, startDestination = HomeGraph, modifier = Modifier.padding(padding)) {
      navigation<ProfileGraph>(startDestination = Profile) {
        composable<Profile> { ProfileScreen() }
        composable<Followers> { FollowersScreen() }   // this depth is restored with the tab
      }
      // ...
    }
  }
}

