// ✅ The picker writes into the CALLER's handle, then pops
@Composable
fun PickerScreen(navController: NavController) {
  AddressList(onPick = { address ->
    navController.previousBackStackEntry
      ?.savedStateHandle
      ?.set("picked_address_id", address.id)     // Bundle-able: an id, never the object
    navController.popBackStack()
  })
}

// ✅ The caller observes its own handle, acts once, then clears the key
@Composable
fun FormScreen(entry: NavBackStackEntry, onPicked: (Long) -> Unit) {
  val handle = entry.savedStateHandle
  val picked by handle.getStateFlow<Long?>("picked_address_id", null)
    .collectAsStateWithLifecycle()               // follows the entry, not the Activity

  LaunchedEffect(picked) {
    val id = picked ?: return@LaunchedEffect
    onPicked(id)
    handle.remove<Long>("picked_address_id")     // or it is re-applied on the next visit
  }
}

