@Composable
fun ProfileRoute(nav: NavController, vm: ProfileViewModel = hiltViewModel()) {
  val lifecycle = LocalLifecycleOwner.current.lifecycle
  LaunchedEffect(Unit) {
    vm.events.flowWithLifecycle(lifecycle).collect { event ->
      when (event) {
        UiEvent.NeedLogin -> nav.navigate(Login) { launchSingleTop = true }
      }
    }
  }
  ProfileContent()
}

