// A custom animation reads the gesture itself, not just its outcome
private val panelBack = object : OnBackPressedCallback(true) {
  override fun handleOnBackStarted(event: BackEventCompat) { panel.prepareForDrag() }
  override fun handleOnBackProgressed(event: BackEventCompat) {
    val dir = if (event.swipeEdge == BackEventCompat.EDGE_LEFT) 1f else -1f
    panel.translationX = event.progress * maxOffset * dir
  }
  override fun handleOnBackCancelled() { panel.springBack() }   // the forgotten half
  override fun handleOnBackPressed() { panel.dismiss() }
}

