@Composable
fun MailScreen(onSettings: () -> Unit) {
  // The pane history: separate from the NavController, and saved across folds
  val panes = rememberListDetailPaneScaffoldNavigator<Long>()
  val scope = rememberCoroutineScope()

  NavigableListDetailPaneScaffold(
    navigator = panes,                 // also installs back handling for the panes
    listPane = {
      AnimatedPane {
        MailList(
          selectedId = panes.currentDestination?.contentKey,
          onOpen = { id ->
            // Expanded width: a pane swap. Compact width: a real push.
            scope.launch { panes.navigateTo(ListDetailPaneScaffoldRole.Detail, id) }
          }
        )
      }
    },
    detailPane = {
      AnimatedPane {
        // Pass the key, never the loaded object — the pane re-reads it itself
        when (val id = panes.currentDestination?.contentKey) {
          null -> EmptyDetailPane()    // a designed state on a tablet, not an error
          else -> MailDetail(id)
        }
      }
    }
  )
}

