@Serializable data object Home : NavKey
@Serializable data object Login : NavKey
@Serializable data class Article(val id: Long) : NavKey

@Composable
fun App(loggedIn: Boolean) {
  // The back stack is state you own; it survives process death because keys are NavKey
  val backStack = rememberNavBackStack(Home)

  NavDisplay(
    backStack = backStack,
    onBack = { count -> repeat(count) { backStack.removeLastOrNull() } },
    entryDecorators = listOf(
      rememberSavedStateNavEntryDecorator(),      // rememberSaveable scoped to the entry
      rememberViewModelStoreNavEntryDecorator()   // viewModel() scoped and cleared with it
    ),
    entryProvider = entryProvider {
      entry<Home> { HomeScreen(onOpen = { id -> backStack.add(Article(id)) }) }
      entry<Article> { key -> ArticleScreen(key.id) }   // the key IS the arguments
      entry<Login> { LoginScreen(onDone = { backStack.remove(Login) }) }
    }
  )

  // A redirect is ordinary Kotlin, not a navigate() inside a composable body
  LaunchedEffect(loggedIn) {
    if (!loggedIn && backStack.lastOrNull() != Login) backStack.add(Login)
  }
}

// popUpTo was always a list operation. Now it is yours — including the guard.
fun MutableList<NavKey>.popUpTo(key: NavKey, inclusive: Boolean = false) {
  val i = indexOfLast { it == key }
  if (i < 0) return
  subList(if (inclusive) i else i + 1, size).clear()
}

